    /**
     * Tests that the method throws InvalidMatrixException if the input is invalid.
     * Note: The constructor itself throws the exception, but we ensure it propagates.
     */
    @Test(expected = InvalidMatrixException.class)
    public void testConstructor_ThrowsException() throws InvalidMatrixException {
        // Creating a matrix that might cause decomposition failure if possible, 
        // but standard way is to pass null or incompatible dimensions if the constructor allows.
        // Since we cannot easily force the internals of the SVD without a mock, 
        // we rely on the fact that the constructor is the entry point.
        new SingularValueDecompositionImpl(null);
    }
